/**
 * App — visitor navigation runtime (no sign-in required).
 *
 * Composition:
 * - Bootstrap: loads nav graph + campus image from configured endpoints
 * - DestinationPicker: building/floor/node search with start/destination selection
 * - MapViewportFloor: floor plan image viewer + route path overlay + floor switcher
 * - RoutePreview: step-by-step directions when route is ready
 * - Accessible mode toggle: switches between standard / accessible routing
 */

import { useCallback, useEffect, useState } from 'react';
import {
  ActivityIndicator,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import {
  IDLE_MAP_BOOTSTRAP_STATE,
  type MapBootstrapState,
  runMapBootstrap,
} from './bootstrap/mapBootstrapState';
import type { NormalizedNavGraph } from './domain/navGraph';
import { MapViewportFloor } from './map/MapViewportFloor';
import type { FloorPlanTarget } from './data/mapApiClient';
import { createMapApiClient } from './data/mapApiClient';
import {
  createInitialMapTransform,
  mapTransformsEqual,
  type MapTransform,
} from './map/mapTransform';
import { DestinationPicker } from './components/destination/DestinationPicker';
import { RoutePreview } from './components/route/RoutePreview';
import { RoutePathOverlay, type RoutePathPoint } from './components/route/RoutePathOverlay';
import { useRouteSelection } from './hooks/useRouteSelection';
import { useRouteSession } from './routing/useRouteSession';
import type { NavNode } from '@shared/types';

/* ─── Helpers ─── */

function nextAttemptFromState(state: MapBootstrapState): number {
  if (state.phase === 'idle') return 1;
  return state.attempt + 1;
}

function phaseMessage(state: MapBootstrapState): string {
  switch (state.phase) {
    case 'idle':    return 'Preparing startup checks.';
    case 'loading': return `Loading ${state.currentPhase} contract from ${state.endpoint}.`;
    case 'ready':   return 'CampusNav map is ready for visitor navigation.';
    case 'error':   return state.message;
  }
}

function formatMetric(value: number): string {
  return Number.isFinite(value) ? value.toFixed(2) : '0';
}

/* ─── Floor target from normalized graph ─── */

function buildFloorTargets(graph: NormalizedNavGraph): FloorPlanTarget[] {
  const targets: FloorPlanTarget[] = [];
  for (const building of graph.graph.buildings) {
    for (const floor of building.floors) {
      targets.push({ buildingId: building.id, floorNumber: floor.floorNumber });
    }
  }
  return targets;
}

/* ─── Map FloorPlanTarget → floorId ─── */

function getFloorId(target: FloorPlanTarget, graph: NormalizedNavGraph): number {
  const key = `${target.buildingId}:${target.floorNumber}`;
  return graph.floorByBuildingAndNumber.get(key)?.floor.id ?? 0;
}

/* ─── Route path from session ready state ─── */

function buildRoutePath(sessionPhase: 'ready', graph: NormalizedNavGraph): RoutePathPoint[] {
  // The path result from MobilePathfindingEngine contains nodeIds
  // We map each to normalized coordinates from the graph
  if (!sessionPhase || sessionPhase !== 'ready') return [];
  return [];
}

/* ─── Component ─── */

export default function App() {
  const [bootstrapState, setBootstrapState] = useState<MapBootstrapState>(IDLE_MAP_BOOTSTRAP_STATE);
  const [transformState, setTransformState] = useState<MapTransform>(createInitialMapTransform());
  const [graph, setGraph] = useState<NormalizedNavGraph | null>(null);
  const [imageUri, setImageUri] = useState<string>('');
  const [activeFloorTarget, setActiveFloorTarget] = useState<FloorPlanTarget | null>(null);
  const [activeFloorId, setActiveFloorId] = useState<number>(0);
  const [routePath, setRoutePath] = useState<RoutePathPoint[]>([]);
  const [accessibleMode, setAccessibleMode] = useState(false);
  const [floorTargets, setFloorTargets] = useState<FloorPlanTarget[]>([]);

  /* ─── Bootstrap ─── */

  const executeBootstrap = useCallback(async (attempt: number) => {
    const result = await runMapBootstrap({ attempt });
    for (const t of result.transitions) {
      if (t.phase === 'loading') console.info('[mobile-bootstrap]', { phase: t.phase, attempt: t.attempt, currentPhase: t.currentPhase, endpoint: t.endpoint });
      if (t.phase === 'ready') console.info('[mobile-bootstrap]', { phase: t.phase, attempt: t.attempt, endpoint: t.image.endpoint });
      if (t.phase === 'error') console.warn('[mobile-bootstrap]', { phase: t.phase, attempt: t.attempt, failedPhase: t.failedPhase, reason: t.reason, recoverable: t.recoverable });
    }
    setBootstrapState(result.state);
  }, []);

  useEffect(() => {
    void executeBootstrap(1);
  }, [executeBootstrap]);

  /* ─── Graph already normalized by bootstrap ─── */

  useEffect(() => {
    if (bootstrapState.phase !== 'ready') return;
    const normalized = bootstrapState.graph;
    setGraph(normalized);
    const targets = buildFloorTargets(normalized);
    setFloorTargets(targets);
  }, [bootstrapState]);

  /* ─── Set initial active floor when floorTargets are first populated ─── */

  const [initialFloorSet, setInitialFloorSet] = useState(false);
  useEffect(() => {
    if (!initialFloorSet && floorTargets.length > 0 && graph) {
      const firstTarget = floorTargets[0];
      setActiveFloorTarget(firstTarget);
      setActiveFloorId(getFloorId(firstTarget, graph));
      setInitialFloorSet(true);
    }
  }, [initialFloorSet, floorTargets, graph]);

  /* ─── Map API client for floor images ─── */

  const mapClient = graph && bootstrapState.phase === 'ready'
    ? createMapApiClient({ baseUrl: bootstrapState.apiBaseUrl })
    : null;

  /* ─── Update floor image when activeFloorTarget changes ─── */

  useEffect(() => {
    if (!mapClient || !activeFloorTarget) { setImageUri(''); return; }
    const url = mapClient.resolveFloorPlanImageUrl(activeFloorTarget);
    setImageUri(url);
  }, [mapClient, activeFloorTarget]);

  /* ─── Route selection ─── */

  const selection = useRouteSelection();

  /* ─── Route session ─── */

  const { sessionState, routeMode, setRouteMode } = graph
    ? useRouteSession({ graph, selection })
    : { sessionState: null, routeMode: 'standard' as const, setRouteMode: () => {} };

  /* ─── Update route mode when accessibleMode changes ─── */

  useEffect(() => {
    setRouteMode(accessibleMode ? 'accessible' : 'standard');
  }, [accessibleMode, setRouteMode]);

  /* ─── Build route path when session is ready ─── */

  useEffect(() => {
    if (!sessionState || sessionState.phase !== 'ready' || !graph) {
      setRoutePath([]);
      return;
    }
    const { path } = sessionState;
    const waypoints: RoutePathPoint[] = [];
    for (const nodeId of path.nodeIds) {
      const record = graph.nodeById.get(nodeId);
      if (!record) continue;
      const node = record.node;
      waypoints.push({ x: node.x, y: node.y, floorId: record.floorId });
    }
    setRoutePath(waypoints);
  }, [sessionState, graph]);

  /* ─── Transform change handler ─── */

  const onTransformChange = useCallback((nextTransform: MapTransform) => {
    setTransformState(current =>
      mapTransformsEqual(current, nextTransform)
        ? current
        : { scale: nextTransform.scale, rotationDeg: nextTransform.rotationDeg, translation: { ...nextTransform.translation } },
    );
  }, []);

  /* ─── Node select handler ─── */

  const onNodeSelect = useCallback((node: NavNode) => {
    selection.setFromTap(node);
    // After selection, set the active floor to the node's floor
    if (graph) {
      const record = graph.nodeById.get(node.id);
      if (record) {
        const target = floorTargets.find(t => t.buildingId === record.buildingId && t.floorNumber === record.floorNumber);
        if (target) {
          setActiveFloorTarget(target);
          setActiveFloorId(getFloorId(target, graph));
        }
      }
    }
  }, [selection, graph, floorTargets]);

  /* ─── Accessible mode toggle ─── */

  const toggleAccessibleMode = useCallback(() => {
    setAccessibleMode(prev => !prev);
  }, []);

  /* ─── Retry handler ─── */

  const onRetryPress = useCallback(() => {
    void executeBootstrap(nextAttemptFromState(bootstrapState));
  }, [executeBootstrap, bootstrapState]);

  /* ─── Phase: idle / loading ─── */

  if (bootstrapState.phase === 'idle' || bootstrapState.phase === 'loading') {
    return (
      <View style={styles.container}>
        <Text style={styles.title}>CampusNav</Text>
        <Text style={styles.subtitle}>Visitor runtime shell (no sign-in)</Text>
        <Text style={styles.statusLabel}>Bootstrap phase: {bootstrapState.phase}</Text>
        <Text style={styles.statusMessage}>{phaseMessage(bootstrapState)}</Text>
        {bootstrapState.phase === 'loading' && (
          <View style={styles.loadingRow}>
            <ActivityIndicator size="small" color="#38bdf8" />
            <Text style={styles.loadingText}>{bootstrapState.currentPhase}</Text>
          </View>
        )}
      </View>
    );
  }

  /* ─── Phase: error ─── */

  if (bootstrapState.phase === 'error') {
    return (
      <View style={styles.container}>
        <Text style={styles.title}>CampusNav</Text>
        <Text style={styles.statusLabel}>Bootstrap phase: error</Text>
        <Text style={styles.errorReason}>Failed phase: {bootstrapState.failedPhase}</Text>
        <Text style={styles.errorReason}>Reason: {bootstrapState.reason}</Text>
        <Text style={styles.errorReason}>Endpoint: {bootstrapState.endpoint ?? 'n/a'}</Text>
        <Pressable onPress={onRetryPress} style={styles.retryButton}>
          <Text style={styles.retryButtonText}>Retry startup</Text>
        </Pressable>
      </View>
    );
  }

  /* ─── Phase: ready ─── */

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.scrollContent}>
      {/* Header */}
      <Text style={styles.title}>CampusNav</Text>
      <Text style={styles.subtitle}>Visitor runtime — no sign-in needed</Text>
      <Text style={styles.statusLabel}>Graph: {graph!.graph.buildings.length} buildings</Text>

      {/* Destination Picker */}
      <View style={styles.section}>
        <DestinationPicker
          graph={graph!}
          selection={selection}
          onNodeSelect={onNodeSelect}
        />
      </View>

      {/* Route Preview (when ready) */}
      {sessionState && sessionState.phase === 'ready' && (
        <View style={styles.section}>
          <RoutePreview
            directions={sessionState.directions}
            accessibleMode={accessibleMode}
          />
        </View>
      )}

      {/* Session phase / route status */}
      {sessionState && (
        <View style={styles.sessionStatus}>
          <Text style={styles.statusLabel}>Route: {sessionState.phase}</Text>
          {sessionState.phase === 'no-route' && (
            <Text style={styles.statusMessage}>No path found between selected locations.</Text>
          )}
          {sessionState.phase === 'error' && (
            <Text style={styles.errorReason}>{sessionState.errorMessage}</Text>
          )}
        </View>
      )}

      {/* Map Viewport with floor switcher */}
      <View style={styles.section}>
        <MapViewportFloor
          activeFloorId={activeFloorId}
          floorTargets={floorTargets}
          activeFloorTarget={activeFloorTarget}
          routePath={routePath}
          onFloorChange={(target) => {
            setActiveFloorTarget(target);
            if (graph) setActiveFloorId(getFloorId(target, graph));
          }}
          showRouteOverlay={sessionState?.phase === 'ready'}
          showFloorSelector={floorTargets.length > 1}
          onTransformChange={onTransformChange}
        />
      </View>

      {/* Accessible mode toggle */}
      <View style={styles.toggleRow}>
        <Text style={styles.toggleLabel}>Accessible mode</Text>
        <Pressable
          style={[styles.toggleButton, accessibleMode && styles.toggleButtonActive]}
          onPress={toggleAccessibleMode}
        >
          <Text style={[styles.toggleButtonText, accessibleMode && styles.toggleButtonTextActive]}>
            {accessibleMode ? 'ON' : 'OFF'}
          </Text>
        </Pressable>
      </View>

      {/* Telemetry */}
      <Text style={styles.telemetryText}>
        viewport scale={formatMetric(transformState.scale)} rotation={formatMetric(transformState.rotationDeg)}°
        tx={formatMetric(transformState.translation.x)} ty={formatMetric(transformState.translation.y)}
      </Text>
    </ScrollView>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#020617',
  },
  scrollContent: {
    paddingHorizontal: 16,
    paddingVertical: 16,
    gap: 12,
  },
  title: {
    color: '#f8fafc',
    fontSize: 28,
    fontWeight: '700',
  },
  subtitle: {
    color: '#cbd5e1',
    fontSize: 14,
    marginBottom: 4,
  },
  statusLabel: {
    color: '#e2e8f0',
    fontSize: 15,
    fontWeight: '600',
  },
  statusMessage: {
    color: '#94a3b8',
    fontSize: 13,
    marginBottom: 4,
  },
  loadingRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  loadingText: {
    color: '#38bdf8',
    fontSize: 13,
  },
  section: {
    minHeight: 120,
    backgroundColor: '#0a0f1e',
    borderRadius: 12,
    overflow: 'hidden',
  },
  sessionStatus: {
    gap: 2,
  },
  errorReason: {
    color: '#fda4af',
    fontSize: 12,
  },
  retryButton: {
    marginTop: 6,
    backgroundColor: '#0f172a',
    borderColor: '#475569',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 14,
    paddingVertical: 8,
    alignSelf: 'flex-start',
  },
  retryButtonText: {
    color: '#f8fafc',
    fontSize: 13,
    fontWeight: '600',
  },
  toggleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 4,
  },
  toggleLabel: {
    color: '#cbd5e1',
    fontSize: 14,
    fontWeight: '500',
  },
  toggleButton: {
    backgroundColor: '#0f172a',
    borderColor: '#334155',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  toggleButtonActive: {
    backgroundColor: '#0c2d4a',
    borderColor: '#38bdf8',
    borderWidth: 1.5,
  },
  toggleButtonText: {
    color: '#94a3b8',
    fontSize: 13,
    fontWeight: '600',
  },
  toggleButtonTextActive: {
    color: '#38bdf8',
  },
  telemetryText: {
    color: '#64748b',
    fontSize: 12,
    fontVariant: ['tabular-nums'],
    marginBottom: 8,
  },
});

/**
 * Guidance state machine — pure computation, no React dependencies.
 *
 * Core types and helper functions for confidence-gated turn-by-turn navigation.
 * Drives the live guidance UI overlay and reroute logic.
 */

import type { DirectionStep, NormalizedNodeRecord } from '../domain/navGraph';
import type { PathResult } from '../domain/navGraph';
import type { RouteSessionReadyState } from './routeSessionState';
import type { NormalizedPoint } from '../../src/shared/gps';

// ============================================================
// Core types
// ============================================================

/**
 * GPS and heading confidence classification.
 *
 * Used by `deriveConfidence` to determine how aggressively
 * the guidance engine trusts the current position fix.
 */
export type ConfidenceLevel = 'high' | 'medium' | 'low' | 'none';

/**
 * Phase of the guidance state machine.
 *
 * State transitions are governed by `deriveNextPhase`:
 * - `idle`          → Initial state; no route loaded
 * - `low-confidence` → Route loaded, but GPS/heading signal is weak
 * - `guiding`       → Route active with confident position; advancing steps
 * - `rerouting`     → Off-route detected, computing new path
 * - `arrived`        → User has reached the destination
 */
export type GuidancePhase =
  | 'idle'
  | 'low-confidence'
  | 'guiding'
  | 'rerouting'
  | 'arrived';

/**
 * Core guidance state for live navigation.
 *
 * Carries the route, current position, and confidence signals needed
 * to drive step advancement and reroute decisions.
 */
export interface GuidanceState {
  phase: GuidancePhase;
  /** The route being followed — must be in 'ready' phase. */
  route: RouteSessionReadyState;
  /** Index of the active DirectionStep (0-based). */
  currentStepIndex: number;
  /** User's current position in normalized [0,1] map space. */
  snappedPosition: NormalizedPoint;
  /** Nearest walkable node ID to the snapped position. */
  snappedNodeId: string;
  /** Device compass heading in degrees (0–360), null if unavailable. */
  heading: number | null;
  /** Heading accuracy in degrees, null if unavailable. */
  headingConfidence: number | null;
  /** Classification of current position fix quality. */
  positionConfidence: ConfidenceLevel;
  /** Unix timestamp (ms) of the last position fix. */
  lastFixTimestamp: number;
  /** Unix timestamp (ms) when off-route was first detected, null if on-route. */
  offRouteDetectedAt: number | null;
  /** Consecutive fixes where off-route was detected. */
  offRouteFixCount: number;
  /** Result of the last reroute computation, null if no reroute has been attempted. */
  rerouteResult: PathResult | null;
}

// ============================================================
// Helper function input types
// ============================================================

export interface PositionFix {
  readonly isConfident: boolean;
  readonly accuracyMeters: number | null;
}

export interface HeadingFix {
  readonly headingDegrees: number | null;
  readonly accuracyDegrees: number | null;
}

// ============================================================
// Pure helper functions
// ============================================================

/**
 * Derive the GPS/heading confidence level from position and heading fixes.
 *
 * Confidence levels:
 * - `high`:   GPS fix is confident AND heading accuracy ≤ 15°
 * - `medium`: GPS fix is confident but heading is missing or unreliable (> 15°)
 * - `low`:    GPS fix not confident but finite (accuracy exists)
 * - `none`:   No GPS fix or infinite accuracy
 */
export function deriveConfidence(
  positionFix: PositionFix,
  headingFix: HeadingFix,
): ConfidenceLevel {
  // none: no GPS fix (null) or infinite accuracy
  if (positionFix.accuracyMeters == null || !Number.isFinite(positionFix.accuracyMeters)) {
    return 'none';
  }

  // low: GPS fix not confident but finite (accuracy exists but > threshold)
  if (!positionFix.isConfident) {
    return 'low';
  }

  // medium: GPS confident but heading missing or unreliable
  if (
    headingFix.headingDegrees == null
    || headingFix.accuracyDegrees == null
    || !Number.isFinite(headingFix.accuracyDegrees)
    || headingFix.accuracyDegrees > 15
  ) {
    return 'medium';
  }

  // high: GPS confident AND heading reliable (≤ 15°)
  return 'high';
}

// ============================================================
// Private helpers
// ============================================================

/**
 * Build an ordered coordinate lookup from a path and its route state.
 * Looks for a nodeById map on the path (production) or falls back to
 * extracting coordinates directly from the node IDs using route.path.nodeById.
 *
 * The path may carry nodeById as an extended property (production path),
 * or the coordinates are resolved via route.path.nodeById (test path).
 */
function buildCoordLookup(
  path: PathResult,
  route: RouteSessionReadyState,
): Map<number, { x: number; y: number }> {
  const coords = new Map<number, { x: number; y: number }>();

  // Try path.nodeById first (production extension pattern)
  const pathAsExtended = path as PathResult & { nodeById?: Map<string, NormalizedNodeRecord> };
  if (pathAsExtended.nodeById && typeof pathAsExtended.nodeById.get === 'function') {
    const nodeById = pathAsExtended.nodeById;
    for (let i = 0; i < path.nodeIds.length; i++) {
      const record = nodeById.get(path.nodeIds[i]);
      if (record) {
        coords.set(i, { x: record.node.x, y: record.node.y });
      }
    }
    return coords;
  }

  // Fallback: resolve via route.path.nodeById (test / production NormalizedNavGraph pattern)
  const routePathAsGraph = route.path as PathResult & { nodeById?: Map<string, NormalizedNodeRecord> };
  const nodeById = routePathAsGraph.nodeById;
  if (nodeById && typeof nodeById.get === 'function') {
    for (let i = 0; i < path.nodeIds.length; i++) {
      const record = nodeById.get(path.nodeIds[i]);
      if (record) {
        coords.set(i, { x: record.node.x, y: record.node.y });
      }
    }
  }

  return coords;
}

/**
 * Compute perpendicular (orthogonal) distance from a point to a line segment.
 *
 * Returns the minimum distance from `point` to any point on the segment
 * between `segStart` and `segEnd`.
 *
 * Uses the standard point-to-segment formula:
 * Let t = dot(P - segStart, segEnd - segStart) / |segEnd - segStart|²
 * Clamp t to [0, 1] (to stay on the segment)
 * Closest point = segStart + t * (segEnd - segStart)
 * Distance = |P - closest_point|
 */
function pointToSegmentDistance(
  point: NormalizedPoint,
  segStart: { x: number; y: number },
  segEnd: { x: number; y: number },
): number {
  const dx = segEnd.x - segStart.x;
  const dy = segEnd.y - segStart.y;
  const lenSq = dx * dx + dy * dy;

  // Degenerate segment (start === end): return distance to the point
  if (lenSq === 0) {
    return Math.sqrt((point.x - segStart.x) ** 2 + (point.y - segStart.y) ** 2);
  }

  // Parameter t for the projection of P onto the segment line
  const t = Math.max(
    0,
    Math.min(
      1,
      ((point.x - segStart.x) * dx + (point.y - segStart.y) * dy) / lenSq,
    ),
  );

  const closestX = segStart.x + t * dx;
  const closestY = segStart.y + t * dy;

  return Math.sqrt((point.x - closestX) ** 2 + (point.y - closestY) ** 2);
}

// ============================================================
// Public route-geometry helpers
// ============================================================

/**
 * Returns true when the user's position is off the active route segment.
 *
 * Detects deviation by measuring perpendicular distance from the current
 * position to the current path segment (from path.nodeIds[currentStepIndex]
 * to path.nodeIds[currentStepIndex + 1]).
 *
 * @param position     User's current snapped position
 * @param currentStepIndex  Which step in the route is active
 * @param path         The current route path
 * @param route        The route session state (provides normalized graph nodeById)
 * @param threshold    Deviation threshold in normalized units (default: 0.05)
 */
export function isOffRoute(
  position: NormalizedPoint,
  currentStepIndex: number,
  path: PathResult,
  route: RouteSessionReadyState,
  threshold = 0.05,
): boolean {
  if (!path.found || path.nodeIds.length < 2) return false;

  const coords = buildCoordLookup(path, route);

  // When at or beyond the last segment, use distance to the final node
  if (currentStepIndex >= path.nodeIds.length - 1) {
    const lastNode = coords.get(path.nodeIds.length - 1);
    if (!lastNode) return false;

    const dist = Math.sqrt(
      (position.x - lastNode.x) ** 2 + (position.y - lastNode.y) ** 2,
    );
    return dist > threshold;
  }

  const startNode = coords.get(currentStepIndex);
  const endNode = coords.get(currentStepIndex + 1);
  if (!startNode || !endNode) return false;

  const distance = pointToSegmentDistance(position, startNode, endNode);
  return distance > threshold;
}

/**
 * Returns true when the user has reached the waypoint at the start of the next step.
 *
 * Uses the same perpendicular-distance approach as `isOffRoute` but with a
 * smaller threshold so that near-passing doesn't trigger an advance mid-segment.
 *
 * @param position        User's current snapped position
 * @param currentStepIndex  Index of the current step (advance check goes to step + 1)
 * @param path            The current route path
 * @param route           The route session state (provides normalized graph nodeById)
 * @param advanceThreshold  Proximity threshold for triggering advance (default: 0.03)
 */
export function shouldAdvanceStep(
  position: NormalizedPoint,
  currentStepIndex: number,
  path: PathResult,
  route: RouteSessionReadyState,
  advanceThreshold = 0.03,
): boolean {
  if (!path.found || path.nodeIds.length < 2) return false;

  const coords = buildCoordLookup(path, route);

  // If the next step index is beyond the node list, use the last node
  const nextStepIdx = currentStepIndex + 1;
  if (nextStepIdx >= path.nodeIds.length) {
    const lastNode = coords.get(path.nodeIds.length - 1);
    if (!lastNode) return false;
    return (
      Math.sqrt(
        (position.x - lastNode.x) ** 2 + (position.y - lastNode.y) ** 2,
      ) <= advanceThreshold
    );
  }

  const startNode = coords.get(currentStepIndex);
  const endNode = coords.get(nextStepIdx);
  if (!startNode || !endNode) return false;

  const distance = pointToSegmentDistance(position, startNode, endNode);
  return distance <= advanceThreshold;
}

/**
 * Derive the next phase from current state and signals.
 *
 * Phase transition rules:
 * - `idle`          → `isConfident` ? 'guiding' : 'low-confidence'
 * - `low-confidence` → `isConfident` ? 'guiding' : stay 'low-confidence'
 * - `guiding`       → `hasArrived` ? 'arrived'
 *                    → `offRouteFixCount >= rerouteConfirmFixes` ? 'rerouting'
 *                    → stay 'guiding'
 * - `rerouting`     → always transitions to 'guiding' (assumes reroute succeeded)
 * - `arrived`       → stays 'arrived'
 *
 * @param state                  Current guidance state
 * @param isConfident            Whether current position is high or medium confidence
 * @param hasArrived             Whether the user has arrived at the destination
 * @param offRouteFixCount       Number of consecutive off-route position fixes
 * @param rerouteConfirmFixes    Fixes required before triggering reroute (default: 3)
 */
export function deriveNextPhase(
  state: GuidanceState,
  isConfident: boolean,
  hasArrived: boolean,
  offRouteFixCount: number,
  rerouteConfirmFixes = 3,
): GuidancePhase {
  switch (state.phase) {
    case 'idle':
      return isConfident ? 'guiding' : 'low-confidence';

    case 'low-confidence':
      return isConfident ? 'guiding' : 'low-confidence';

    case 'guiding':
      if (hasArrived) return 'arrived';
      if (offRouteFixCount >= rerouteConfirmFixes) return 'rerouting';
      return 'guiding';

    case 'rerouting':
      // Assumes the caller has set rerouteResult; transitions back to guiding
      return 'guiding';

    case 'arrived':
      return 'arrived';
  }
}

/**
 * Return the active DirectionStep for the current step index.
 *
 * Returns null when there is no active route, no directions have been generated,
 * or the current step index is out of bounds.
 */
export function getActiveStep(state: GuidanceState): DirectionStep | null {
  const { route, currentStepIndex } = state;
  if (route.phase !== 'ready') return null;
  if (!route.directions) return null;
  const { steps } = route.directions;
  if (currentStepIndex < 0 || currentStepIndex >= steps.length) return null;
  return steps[currentStepIndex] ?? null;
}

/**
 * MobilePathfindingEngine — custom A* pathfinding on NormalizedNavGraph.
 *
 * Avoids the ngraph.graph dependency by implementing A* directly using
 * the normalized graph structure produced by normalizeNavGraph().
 *
 * Features:
 * - Dual-mode routing: standard vs accessible
 * - Inter-floor traversal via stairs/elevator/ramp connectors
 * - Euclidean heuristic with floor-level penalty
 * - Explicit result types (no exceptions for not-found)
 */

import type { NavFloor, NavNode } from '../../src/shared/types';
import type {
  DirectionStep,
  DirectionsResult,
  NormalizedEdgeRecord,
  NormalizedNavGraph,
  NormalizedNodeRecord,
  PathResult,
  PathSegment,
  RouteMode,
  StepIcon,
} from '../domain/navGraph';

// ============================================================
// Priority Queue (binary heap)
// ============================================================

interface QueueEntry {
  nodeId: string;
  gScore: number;
  fScore: number;
}

/**
 * Min-heap priority queue for A* frontier.
 */
class PriorityQueue {
  private heap: QueueEntry[] = [];

  push(nodeId: string, gScore: number, fScore: number): void {
    this.heap.push({ nodeId, gScore, fScore });
    this.bubbleUp(this.heap.length - 1);
  }

  pop(): QueueEntry | undefined {
    if (this.heap.length === 0) return undefined;
    const min = this.heap[0];
    const last = this.heap.pop()!;
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this.bubbleDown(0);
    }
    return min;
  }

  isEmpty(): boolean {
    return this.heap.length === 0;
  }

  private bubbleUp(index: number): void {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (this.heap[parent].fScore <= this.heap[index].fScore) break;
      [this.heap[parent], this.heap[index]] = [this.heap[index], this.heap[parent]];
      index = parent;
    }
  }

  private bubbleDown(index: number): void {
    const length = this.heap.length;
    while (true) {
      const left = 2 * index + 1;
      const right = 2 * index + 2;
      let smallest = index;

      if (left < length && this.heap[left].fScore < this.heap[smallest].fScore) {
        smallest = left;
      }
      if (right < length && this.heap[right].fScore < this.heap[smallest].fScore) {
        smallest = right;
      }
      if (smallest === index) break;
      [this.heap[smallest], this.heap[index]] = [this.heap[index], this.heap[smallest]];
      index = smallest;
    }
  }
}

// ============================================================
// Constants
// ============================================================

/** Weight for inter-floor traversal in standard mode (elevator/ramp) */
const INTER_FLOOR_STANDARD_WEIGHT = 0.3;
/** Weight for inter-floor traversal via elevator in accessible mode */
const INTER_FLOOR_ELEVATOR_WEIGHT = 0.45;
/** Weight for inter-floor traversal via ramp in accessible mode */
const INTER_FLOOR_RAMP_WEIGHT = 0.45;
/** Stairs are not accessible — used as sentinel for inaccessible inter-floor traversal */
const INTER_FLOOR_STAIRS_INACCESSIBLE = Infinity;
/** Penalty multiplier for floor-level difference in heuristic */
const FLOOR_PENALTY_PER_LEVEL = 0.5;

// ============================================================
// Engine
// ============================================================

/**
 * Custom A* pathfinding engine for mobile.
 *
 * Operates directly on NormalizedNavGraph, avoiding ngraph.graph dependency.
 */
export class MobilePathfindingEngine {
  private readonly graph: NormalizedNavGraph;

  constructor(graph: NormalizedNavGraph) {
    this.graph = graph;
  }

  /**
   * Find a route between two nodes.
   *
   * @param fromId - Source node ID
   * @param toId - Destination node ID
   * @param mode - 'standard' or 'accessible'
   * @returns PathResult with found status, ordered nodeIds, segments, and totalDistance
   */
  findRoute(fromId: string, toId: string, mode: RouteMode): PathResult {
    // Trivial same-node case
    if (fromId === toId) {
      return { found: true, nodeIds: [fromId], totalDistance: 0, segments: [] };
    }

    // Node existence guards
    if (!this.graph.nodeById.has(fromId) || !this.graph.nodeById.has(toId)) {
      return { found: false, nodeIds: [], totalDistance: 0, segments: [] };
    }

    const { nodeIds, segments, totalDistance } = this.astar(fromId, toId, mode);

    if (nodeIds.length === 0) {
      return { found: false, nodeIds: [], totalDistance: 0, segments: [] };
    }

    return { found: true, nodeIds, totalDistance, segments };
  }

  /**
   * A* search implementation.
   */
  private astar(
    startId: string,
    goalId: string,
    mode: RouteMode,
  ): { nodeIds: string[]; segments: PathSegment[]; totalDistance: number } {
    const frontier = new PriorityQueue();
    const cameFrom = new Map<string, { nodeId: string; edge: NormalizedEdgeRecord }>();
    const gScore = new Map<string, number>();
    const visited = new Set<string>();

    const startRecord = this.graph.nodeById.get(startId)!;
    const goalRecord = this.graph.nodeById.get(goalId)!;

    const startHeuristic = this.heuristic(startRecord, goalRecord);
    frontier.push(startId, 0, startHeuristic);
    gScore.set(startId, 0);

    while (!frontier.isEmpty()) {
      const current = frontier.pop()!;
      const currentId = current.nodeId;

      // Goal reached — reconstruct path
      if (currentId === goalId) {
        return this.reconstructPath(startId, goalId, cameFrom, mode);
      }

      if (visited.has(currentId)) continue;
      visited.add(currentId);

      const neighbors = this.getNeighbors(currentId, mode);

      for (const { neighborId, edgeRecord, edgeWeight } of neighbors) {
        if (visited.has(neighborId)) continue;

        const tentativeG = (gScore.get(currentId) ?? Infinity) + edgeWeight;

        if (tentativeG < (gScore.get(neighborId) ?? Infinity)) {
          gScore.set(neighborId, tentativeG);
          cameFrom.set(neighborId, { nodeId: currentId, edge: edgeRecord });

          const neighborRecord = this.graph.nodeById.get(neighborId)!;
          const f = tentativeG + this.heuristic(neighborRecord, goalRecord);
          frontier.push(neighborId, tentativeG, f);
        }
      }
    }

    // No path found
    return { nodeIds: [], segments: [], totalDistance: 0 };
  }

  /**
   * Reconstruct path from A* search results.
   */
  private reconstructPath(
    startId: string,
    goalId: string,
    cameFrom: Map<string, { nodeId: string; edge: NormalizedEdgeRecord }>,
    mode: RouteMode,
  ): { nodeIds: string[]; segments: PathSegment[]; totalDistance: number } {
    const nodeIds: string[] = [];
    const segments: PathSegment[] = [];
    let currentId: string | undefined = goalId;
    let totalDistance = 0;

    while (currentId !== undefined) {
      nodeIds.unshift(currentId);

      const prev = cameFrom.get(currentId);
      if (prev === undefined) break;

      const { nodeId: prevId, edge } = prev;
      const distance =
        mode === 'accessible' ? edge.effectiveAccessibleWeight : edge.edge.standardWeight;

      segments.unshift({ fromId: prevId, toId: currentId, distance });
      totalDistance += distance;

      currentId = prevId;
    }

    nodeIds.unshift(startId);
    return { nodeIds, segments, totalDistance };
  }

  /**
   * Get neighbors of a node, including inter-floor connections.
   */
  private getNeighbors(
    nodeId: string,
    mode: RouteMode,
  ): Array<{ neighborId: string; edgeRecord: NormalizedEdgeRecord; edgeWeight: number }> {
    const neighbors: Array<{
      neighborId: string;
      edgeRecord: NormalizedEdgeRecord;
      edgeWeight: number;
    }> = [];

    // Same-floor neighbors via outgoing edges
    const outgoingEdges = this.graph.outgoingEdgesByNodeId.get(nodeId) ?? [];
    for (const edgeRecord of outgoingEdges) {
      if (mode === 'accessible' && !edgeRecord.edge.accessible) {
        // Skip non-accessible edges in accessible mode
        continue;
      }

      const weight = mode === 'accessible' ? edgeRecord.effectiveAccessibleWeight : edgeRecord.edge.standardWeight;

      neighbors.push({
        neighborId: edgeRecord.edge.targetId,
        edgeRecord,
        edgeWeight: weight,
      });

      // Add reverse edge for bidirectional connections
      if (edgeRecord.edge.bidirectional) {
        neighbors.push({
          neighborId: edgeRecord.edge.sourceId,
          edgeRecord,
          edgeWeight: weight,
        });
      }
    }

    // Inter-floor neighbors via connector nodes
    const nodeRecord = this.graph.nodeById.get(nodeId);
    if (nodeRecord) {
      const node = nodeRecord.node;

      // Check for connection to floor above
      if (node.connectsToNodeAboveId && node.connectsToFloorAboveId !== undefined) {
        const aboveNeighborId = node.connectsToNodeAboveId;
        if (this.graph.nodeById.has(aboveNeighborId)) {
          const interFloorWeight = this.interFloorWeight(node.type, 'up', mode);
          const syntheticEdgeRecord: NormalizedEdgeRecord = {
            buildingId: nodeRecord.buildingId,
            floorId: node.floorId,
            edge: {
              id: `interfloor-${nodeId}-${aboveNeighborId}`,
              sourceId: nodeId,
              targetId: aboveNeighborId,
              standardWeight: interFloorWeight,
              accessibleWeight: interFloorWeight,
              accessible: node.type === 'elevator' || node.type === 'ramp',
              bidirectional: true,
            },
            effectiveAccessibleWeight: interFloorWeight,
          };

          neighbors.push({
            neighborId: aboveNeighborId,
            edgeRecord: syntheticEdgeRecord,
            edgeWeight: interFloorWeight,
          });
        }
      }

      // Check for connection to floor below
      if (node.connectsToNodeBelowId && node.connectsToFloorBelowId !== undefined) {
        const belowNeighborId = node.connectsToNodeBelowId;
        if (this.graph.nodeById.has(belowNeighborId)) {
          const interFloorWeight = this.interFloorWeight(node.type, 'down', mode);
          const syntheticEdgeRecord: NormalizedEdgeRecord = {
            buildingId: nodeRecord.buildingId,
            floorId: node.floorId,
            edge: {
              id: `interfloor-${nodeId}-${belowNeighborId}`,
              sourceId: nodeId,
              targetId: belowNeighborId,
              standardWeight: interFloorWeight,
              accessibleWeight: interFloorWeight,
              accessible: node.type === 'elevator' || node.type === 'ramp',
              bidirectional: true,
            },
            effectiveAccessibleWeight: interFloorWeight,
          };

          neighbors.push({
            neighborId: belowNeighborId,
            edgeRecord: syntheticEdgeRecord,
            edgeWeight: interFloorWeight,
          });
        }
      }
    }

    return neighbors;
  }

  /**
   * Calculate weight for inter-floor traversal.
   */
  private interFloorWeight(
    nodeType: string,
    direction: 'up' | 'down',
    mode: RouteMode,
  ): number {
    if (nodeType === 'elevator') {
      return mode === 'accessible' ? INTER_FLOOR_ELEVATOR_WEIGHT : INTER_FLOOR_STANDARD_WEIGHT;
    }
    if (nodeType === 'ramp') {
      return mode === 'accessible' ? INTER_FLOOR_RAMP_WEIGHT : INTER_FLOOR_STANDARD_WEIGHT;
    }
    if (nodeType === 'stairs') {
      return mode === 'accessible' ? INTER_FLOOR_STAIRS_INACCESSIBLE : INTER_FLOOR_STANDARD_WEIGHT;
    }
    // Default fallback
    return mode === 'accessible' ? INTER_FLOOR_STAIRS_INACCESSIBLE : INTER_FLOOR_STANDARD_WEIGHT;
  }

  /**
   * Euclidean heuristic with floor-level penalty.
   * Admissible: never overestimates true cost.
   */
  private heuristic(a: NormalizedNodeRecord, b: NormalizedNodeRecord): number {
    const dx = b.node.x - a.node.x;
    const dy = b.node.y - a.node.y;
    const euclidean = Math.sqrt(dx * dx + dy * dy);
    const floorDiff = Math.abs(b.floorNumber - a.floorNumber);
    return euclidean + floorDiff * FLOOR_PENALTY_PER_LEVEL;
  }
}

/**
 * Route session state machine — pure computation, no React dependencies.
 *
 * Coordinates pathfinding (T01 engine) and direction generation (T01)
 * into a single discriminated union state that drives the UI.
 */

import type { NavNode } from '../../src/shared/types';
import type {
  DirectionsResult,
  NormalizedNavGraph,
  PathResult,
  RouteMode,
} from '../domain/navGraph';
import { MobilePathfindingEngine } from './pathfindingEngine';
import { generateDirections } from './generateDirections';

// ============================================================
// Phase types
// ============================================================

export type RouteSessionPhase =
  | 'idle'
  | 'computing'
  | 'ready'
  | 'no-route'
  | 'error';

// ============================================================
// Discriminated union state types
// ============================================================

export interface RouteSessionIdleState {
  readonly phase: 'idle';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionComputingState {
  readonly phase: 'computing';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionReadyState {
  readonly phase: 'ready';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: PathResult;
  readonly directions: DirectionsResult;
  readonly errorMessage: null;
}

export interface RouteSessionNoRouteState {
  readonly phase: 'no-route';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionErrorState {
  readonly phase: 'error';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: string;
}

/**
 * Discriminated union of all route session states.
 *
 * Discriminant key: `phase`
 *
 * Phase meanings:
 * - `idle`:    No start/destination yet
 * - `computing`: Currently computing (sync, so only an intermediate phase)
 * - `ready`:  Route found — path and directions available
 * - `no-route`: Start & dest selected but no path exists
 * - `error`:  Node not present in graph or other error
 */
export type RouteSessionState =
  | RouteSessionIdleState
  | RouteSessionComputingState
  | RouteSessionReadyState
  | RouteSessionNoRouteState
  | RouteSessionErrorState;

// ============================================================
// Options
// ============================================================

export interface RouteSessionOptions {
  readonly graph: NormalizedNavGraph;
  readonly mode: RouteMode;
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
}

// ============================================================
// Private helpers
// ============================================================

/**
 * Compute directions from a found path result.
 * Uses nodeMap and floorMap from the normalized graph.
 */
function computeDirections(
  path: PathResult,
  mode: RouteMode,
  graph: NormalizedNavGraph,
): DirectionsResult {
  // Extract plain NavNode objects from normalized records
  const nodeMap = new Map<string, NavNode>();
  for (const [id, record] of graph.nodeById) {
    nodeMap.set(id, record.node);
  }

  // Extract plain NavFloor objects from normalized records
  const floorMap = new Map<number, import('../../src/shared/types').NavFloor>();
  for (const [id, record] of graph.floorById) {
    floorMap.set(id, record.floor);
  }

  return generateDirections(
    path.nodeIds,
    nodeMap,
    mode,
    floorMap,
  );
}

// ============================================================
// Main computation function
// ============================================================

/**
 * Compute a route session state synchronously.
 *
 * A* is fast enough that no async boundary is needed.
 * The 'computing' phase is included for UI tooling (DevTools)
 * and to make the phase model complete.
 *
 * Transitions:
 * - start === null || destination === null → 'idle'
 * - start/dest valid but not in graph         → 'error'
 * - start/dest in graph, no path found        → 'no-route'
 * - start/dest in graph, path found           → 'ready'
 */
export function computeRouteSession(options: RouteSessionOptions): RouteSessionState {
  const { graph, mode, start, destination } = options;

  // Guard: missing input
  if (start === null || destination === null) {
    return {
      phase: 'idle',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Guard: nodes not in graph
  if (!graph.nodeById.has(start.id) || !graph.nodeById.has(destination.id)) {
    return {
      phase: 'error',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: 'One or both selected nodes are not present in the navigation graph.',
    };
  }

  // Guard: start === destination
  if (start.id === destination.id) {
    return {
      phase: 'idle',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Compute path
  const engine = new MobilePathfindingEngine(graph);
  const path = engine.findRoute(start.id, destination.id, mode);

  if (!path.found) {
    return {
      phase: 'no-route',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Compute directions
  const directions = computeDirections(path, mode, graph);

  return {
    phase: 'ready',
    start,
    destination,
    routeMode: mode,
    path,
    directions,
    errorMessage: null,
  };
}

/**
 * Guidance session orchestrator — wires useRouteSession, useCurrentPosition,
 * and the guidance state machine into a live guidance loop.
 *
 * Responsibilities:
 * - Subscribes to GPS + heading via useCurrentPosition
 * - Projects lat/lng → normalized map coords → nearest walkable node
 * - Drives phase transitions (idle → guiding → rerouting → arrived)
 * - Advances currentStepIndex as the user progresses
 * - Triggers reroute via MobilePathfindingEngine when off-route
 * - Exposes manual confirmPosition() for user-asserted location
 */

import { useCallback, useEffect, useRef, useState } from 'react';

import {
  projectLatLngToNormalizedPoint,
  snapLatLngToNearestWalkableNode,
} from '../../src/shared/gps';
import type {
  DirectionsResult,
  NormalizedNavGraph,
  PathResult,
} from '../domain/navGraph';
import {
  deriveConfidence,
  isOffRoute,
  shouldAdvanceStep,
} from '../routing/guidanceState';
import type {
  ConfidenceLevel,
  GuidancePhase,
  GuidanceState,
  HeadingFix,
  PositionFix,
} from '../routing/guidanceState';
import { MobilePathfindingEngine } from '../routing/pathfindingEngine';
import type { RouteSessionReadyState } from '../routing/routeSessionState';
import { useCurrentPosition } from './useCurrentPosition';
import type {
  HeadingData,
  PositionFix as HookPositionFix,
} from './useCurrentPosition';

// ============================================================
// Props
// ============================================================

export interface UseGuidanceSessionProps {
  /** Normalized navigation graph (from useRouteSelection). */
  graph: NormalizedNavGraph;
  /** Ready route from useRouteSession (S02). Must have phase === 'ready'. */
  route: RouteSessionReadyState;
  /** Minimum ms between position updates. Default: 2000. */
  updateIntervalMs?: number;
  /** Off-route threshold in normalized map units. Default: 0.05. */
  offRouteThreshold?: number;
  /** Consecutive off-route fixes needed before reroute. Default: 2. */
  rerouteConfirmFixes?: number;
  /** Minimum ms between reroute triggers. Default: 5000. */
  rerouteCooldownMs?: number;
  /** Max accuracy (m) for confident GPS fix. Default: 50. */
  maxAccuracyMeters?: number;
}

// ============================================================
// Result
// ============================================================

export interface UseGuidanceSessionResult {
  /** Live guidance state snapshot (use for React rendering). */
  guidanceState: GuidanceState;
  /**
   * Begin live guidance from the current GPS position.
   * Snaps to the nearest walkable node and transitions phase.
   */
  startGuidance: () => void;
  /** Halt live guidance and return to idle. */
  stopGuidance: () => void;
  /**
   * User asserts their location by tapping a node on the map.
   * Resets offRouteFixCount and re-derives confidence.
   */
  confirmPosition: (nodeId: string) => void;
}

// ============================================================
// Pure helpers (extracted for testability)
// ============================================================

/** Convert useCurrentPosition fix → guidance state PositionFix */
export function hookFixToStateFix(fix: HookPositionFix | null): PositionFix {
  if (!fix) {
    return { isConfident: false, accuracyMeters: null };
  }
  return {
    isConfident: fix.accuracyMeters != null && isFinite(fix.accuracyMeters),
    accuracyMeters: fix.accuracyMeters,
  };
}

/** Convert useCurrentPosition heading → guidance state HeadingFix */
export function hookHeadingToStateHeading(
  heading: HeadingData | null,
): HeadingFix {
  if (!heading) {
    return { headingDegrees: null, accuracyDegrees: null };
  }
  return {
    headingDegrees: heading.headingDegrees,
    accuracyDegrees: heading.accuracyDegrees,
  };
}

// ============================================================
// Hook implementation
// ============================================================

/**
 * Guidance session hook.
 *
 * Subscribes to GPS + heading, drives phase transitions, and exposes
 * startGuidance / stopGuidance / confirmPosition for UI control.
 */
export function useGuidanceSession({
  graph,
  route,
  updateIntervalMs = 2000,
  offRouteThreshold = 0.05,
  rerouteConfirmFixes = 2,
  rerouteCooldownMs = 5000,
  maxAccuracyMeters = 50,
}: UseGuidanceSessionProps): UseGuidanceSessionResult {
  // ── Guidance state ───────────────────────────────────────────────────────
  //
  // guidanceStateRef: updated on every position fix without triggering
  // re-renders. Isolates high-frequency position updates from React's
  // render cycle.
  const guidanceStateRef = useRef<GuidanceState>({
    phase: 'idle',
    route,
    currentStepIndex: 0,
    snappedPosition: { x: 0, y: 0 },
    snappedNodeId: '',
    heading: null,
    headingConfidence: null,
    positionConfidence: 'none',
    lastFixTimestamp: 0,
    offRouteDetectedAt: null,
    offRouteFixCount: 0,
    rerouteResult: null,
  });

  // guidanceState: React state snapshot — updated after each position
  // processing pass so components can subscribe and re-render.
  const [guidanceState, setGuidanceState] = useState<GuidanceState>(
    guidanceStateRef.current,
  );

  // ── GPS + heading subscription ──────────────────────────────────────────
  const { position: hookPosition, heading: hookHeading } = useCurrentPosition({
    updateIntervalMs,
    maxAccuracyMeters,
  });

  // ── Callback ref for position processing ─────────────────────────────────
  //
  // Uses a ref callback so we can call the same processing logic
  // from multiple useEffect entry points without stale closures.
  const processPositionRef = useRef<((fix: HookPositionFix | null) => void) | null>(
    null,
  );

  // ── On position update ───────────────────────────────────────────────────
  useEffect(() => {
    const fix = hookPosition;
    processPositionRef.current?.(fix);
  }, [hookPosition]);

  // ── Build the mutable guidance state machine (runs on every fix) ─────────
  //
  // This function is assigned to processPositionRef.current inside a
  // useEffect with the correct closure. We declare it here for clarity.
  function processFix(fix: HookPositionFix | null): void {
    const state = guidanceStateRef.current;

    // Skip processing when guidance is not active.
    if (state.phase === 'idle') return;
    if (state.phase === 'arrived') return;

    // Cannot process without a snapped node.
    if (!state.snappedNodeId) {
      setGuidanceState({ ...state, positionConfidence: 'none' });
      return;
    }

    // ── Project + snap ────────────────────────────────────────────────────
    // Find floor bounds for the current snapped node.
    const snappedRecord = graph.nodeById.get(state.snappedNodeId);
    const floorBounds = snappedRecord
      ? graph.floorById.get(snappedRecord.floorId)?.floor.gpsBounds ?? null
      : null;

    let snappedPosition = state.snappedPosition;
    let snappedNodeId = state.snappedNodeId;

    if (fix && floorBounds) {
      const projected = projectLatLngToNormalizedPoint(
        fix.latitude,
        fix.longitude,
        floorBounds,
      );

      if (projected) {
        snappedPosition = projected;
        const snapResult = snapLatLngToNearestWalkableNode(
          fix.latitude,
          fix.longitude,
          floorBounds,
          Array.from(graph.nodeById.values()).map(r => r.node),
          Array.from(graph.edgeById.values()).map(r => r.edge),
        );

        if (snapResult) {
          snappedNodeId = snapResult.node.id;
        }
      }
    }

    // ── Derive confidence ─────────────────────────────────────────────────
    const positionFix: PositionFix = hookFixToStateFix(fix);
    const headingFix: HeadingFix = hookHeadingToStateHeading(hookHeading);
    const confidence: ConfidenceLevel = deriveConfidence(positionFix, headingFix);

    const isConfident = confidence === 'high' || confidence === 'medium';

    // ── Mutable state machine (runs synchronously) ─────────────────────────
    let currentPhase: GuidancePhase = state.phase;
    let currentStepIndex = state.currentStepIndex;
    let offRouteFixCount = state.offRouteFixCount;
    let offRouteDetectedAt = state.offRouteDetectedAt;
    let rerouteResult: PathResult | null = state.rerouteResult;

    if (!isConfident) {
      // Low-confidence: pause advancement, stay in low-confidence.
      currentPhase = 'low-confidence';
    } else {
      // Confident: check geometry.
      const offRoute = isOffRoute(
        snappedPosition,
        currentStepIndex,
        state.route.path,
        state.route,
        offRouteThreshold,
      );

      if (offRoute) {
        // Accumulate off-route fix count.
        if (offRouteFixCount === 0) {
          offRouteDetectedAt = Date.now();
        }
        offRouteFixCount += 1;

        // Trigger reroute only after enough consecutive fixes AND cooldown elapsed.
        const cooldownElapsed =
          offRouteDetectedAt === null ||
          Date.now() - offRouteDetectedAt >= rerouteCooldownMs;

        if (offRouteFixCount >= rerouteConfirmFixes && cooldownElapsed) {
          currentPhase = 'rerouting';
        }
      } else {
        // On route: reset counter.
        offRouteFixCount = 0;
        offRouteDetectedAt = null;

        // Check for step advancement.
        const advance = shouldAdvanceStep(
          snappedPosition,
          currentStepIndex,
          state.route.path,
          state.route,
        );

        if (advance) {
          currentStepIndex += 1;
        }

        // Check for arrival.
        if (currentStepIndex >= state.route.path.nodeIds.length) {
          currentPhase = 'arrived';
        } else {
          currentPhase = 'guiding';
        }
      }
    }

    // ── Commit state update ───────────────────────────────────────────────
    const newState: GuidanceState = {
      ...state,
      phase: currentPhase,
      currentStepIndex,
      snappedPosition,
      snappedNodeId,
      heading: hookHeading?.headingDegrees ?? null,
      headingConfidence: hookHeading?.accuracyDegrees ?? null,
      positionConfidence: confidence,
      lastFixTimestamp: fix?.timestamp ?? Date.now(),
      offRouteFixCount,
      offRouteDetectedAt,
      rerouteResult,
    };

    guidanceStateRef.current = newState;
    setGuidanceState(newState);
  }

  // ── Mount processing callback ref ──────────────────────────────────────────
  //
  // Must be inside useEffect so all ref captures (graph, route, thresholds)
  // are stable across renders.
  useEffect(() => {
    processPositionRef.current = processFix;
  });

  // ── Reroute: called when phase transitions to 'rerouting' ───────────────
  useEffect(() => {
    if (guidanceStateRef.current.phase !== 'rerouting') return;

    const state = guidanceStateRef.current;
    const engine = new MobilePathfindingEngine(graph);

    const newPath = engine.findRoute(
      state.snappedNodeId,
      state.route.destination!.id,
      state.route.routeMode,
    );

    if (newPath.found) {
      const newDirections = recomputeDirections(newPath, state.route, graph);
      const newState: GuidanceState = {
        ...state,
        phase: 'guiding',
        route: {
          ...state.route,
          path: newPath,
          directions: newDirections,
        } as RouteSessionReadyState,
        offRouteFixCount: 0,
        offRouteDetectedAt: null,
        currentStepIndex: 0,
      };
      guidanceStateRef.current = newState;
      setGuidanceState(newState);
    } else {
      // No path from current position — user must manually pick a new destination.
      const newState: GuidanceState = {
        ...state,
        phase: 'low-confidence',
        offRouteFixCount: 0,
        offRouteDetectedAt: null,
      };
      guidanceStateRef.current = newState;
      setGuidanceState(newState);
    }
  }, [guidanceState.phase, graph]);

  // ── startGuidance ────────────────────────────────────────────────────────
  const startGuidance = useCallback(() => {
    // Find floor bounds for the snapped node's floor.
    const snappedRecord = graph.nodeById.get(guidanceStateRef.current.snappedNodeId);
    const floorBounds = snappedRecord
      ? graph.floorById.get(snappedRecord.floorId)?.floor.gpsBounds ?? null
      : null;

    let snappedNodeId = guidanceStateRef.current.snappedNodeId;
    let snappedPosition = guidanceStateRef.current.snappedPosition;

    const fix = hookPosition;
    if (fix && floorBounds) {
      const projected = projectLatLngToNormalizedPoint(
        fix.latitude,
        fix.longitude,
        floorBounds,
      );
      if (projected) {
        snappedPosition = projected;
        const snapResult = snapLatLngToNearestWalkableNode(
          fix.latitude,
          fix.longitude,
          floorBounds,
          Array.from(graph.nodeById.values()).map(r => r.node),
          Array.from(graph.edgeById.values()).map(r => r.edge),
        );
        if (snapResult) {
          snappedNodeId = snapResult.node.id;
        }
      }
    }

    const positionFix: PositionFix = hookFixToStateFix(fix);
    const headingFix: HeadingFix = hookHeadingToStateHeading(hookHeading);
    const confidence = deriveConfidence(positionFix, headingFix);
    const isConfident = confidence === 'high' || confidence === 'medium';

    const phase: GuidancePhase = isConfident ? 'guiding' : 'low-confidence';

    const newState: GuidanceState = {
      ...guidanceStateRef.current,
      phase,
      currentStepIndex: 0,
      snappedPosition,
      snappedNodeId,
      heading: hookHeading?.headingDegrees ?? null,
      headingConfidence: hookHeading?.accuracyDegrees ?? null,
      positionConfidence: confidence,
      lastFixTimestamp: fix?.timestamp ?? Date.now(),
      offRouteFixCount: 0,
      offRouteDetectedAt: null,
      rerouteResult: null,
    };

    guidanceStateRef.current = newState;
    setGuidanceState(newState);
    console.log('[Guidance] guidance-started', { phase, snappedNodeId });
  }, [graph, hookPosition, hookHeading]);

  // ── stopGuidance ─────────────────────────────────────────────────────────
  const stopGuidance = useCallback(() => {
    const newState: GuidanceState = {
      ...guidanceStateRef.current,
      phase: 'idle',
      snappedPosition: { x: 0, y: 0 },
      snappedNodeId: '',
      heading: null,
      headingConfidence: null,
      positionConfidence: 'none',
      lastFixTimestamp: 0,
      offRouteDetectedAt: null,
      offRouteFixCount: 0,
      rerouteResult: null,
    };

    guidanceStateRef.current = newState;
    setGuidanceState(newState);
    console.log('[Guidance] guidance-stopped');
  }, []);

  // ── confirmPosition ──────────────────────────────────────────────────────
  const confirmPosition = useCallback(
    (nodeId: string) => {
      const nodeRecord = graph.nodeById.get(nodeId);
      if (!nodeRecord || !route.destination) return;

      const floorBounds =
        graph.floorById.get(nodeRecord.floorId)?.floor.gpsBounds ?? null;

      let snappedPosition = guidanceStateRef.current.snappedPosition;
      if (floorBounds) {
        snappedPosition = { x: nodeRecord.node.x, y: nodeRecord.node.y };
      }

      const positionFix: PositionFix = hookFixToStateFix(hookPosition);
      const headingFix: HeadingFix = hookHeadingToStateHeading(hookHeading);
      const confidence = deriveConfidence(positionFix, headingFix);
      const isConfident = confidence === 'high' || confidence === 'medium';

      const phase: GuidancePhase = isConfident ? 'guiding' : 'low-confidence';

      const newState: GuidanceState = {
        ...guidanceStateRef.current,
        phase,
        snappedPosition,
        snappedNodeId: nodeId,
        positionConfidence: confidence,
        offRouteFixCount: 0,
        offRouteDetectedAt: null,
      };

      guidanceStateRef.current = newState;
      setGuidanceState(newState);
    },
    [graph, route.destination, hookPosition, hookHeading],
  );

  return {
    guidanceState,
    startGuidance,
    stopGuidance,
    confirmPosition,
  };
}

